    65	void
    66	deleteServerSecureChannel(UA_Server *server, UA_SecureChannel *channel) {
    67	    UA_LOCK_ASSERT(&server->serviceMutex);
    68	
    69	    /* Clean up the SecureChannel. This is the only place where
    70	     * UA_SecureChannel_clear must be called within the server code-base.
    71	     *
    72	     * Activated sessions are detached so they can be re-activated on a new
    73	     * channel. Non-activated sessions are deleted (Part 4, §5.6.3). */
    74	    while(channel->sessions) {
    75	        UA_Session *session = channel->sessions;
    76	        if(!session->activated)
    77	            UA_Session_remove(server, session, UA_SHUTDOWNREASON_PURGE);
    78	        else
    79	            UA_Session_detachFromSecureChannel(server, session);
    80	    }
    81	
    82	    /* Detach the channel from the server list */
    83	    TAILQ_REMOVE(&server->channels, channel, serverEntry);
    84	
    85	    UA_ServerConfig *sc = &server->config;
    86	
    87	    /* Update the statistics */
    88	    UA_SecureChannelStatistics *scs = &server->secureChannelStatistics;
    89	    scs->currentChannelCount--;
    90	    switch(channel->shutdownReason) {
    91	    case UA_SHUTDOWNREASON_CLOSE:
    92	        UA_LOG_INFO_CHANNEL(sc->logging, channel, "SecureChannel closed");
    93	        break;
    94	    case UA_SHUTDOWNREASON_TIMEOUT:
    95	        UA_LOG_INFO_CHANNEL(sc->logging, channel, "SecureChannel closed due to timeout");
    96	        scs->channelTimeoutCount++;
    97	        break;
    98	    case UA_SHUTDOWNREASON_PURGE:
    99	        UA_LOG_INFO_CHANNEL(sc->logging, channel, "SecureChannel was purged");
   100	        scs->channelPurgeCount++;
   101	        break;
   102	    case UA_SHUTDOWNREASON_REJECT:
   103	    case UA_SHUTDOWNREASON_SECURITYREJECT:
   104	        UA_LOG_INFO_CHANNEL(sc->logging, channel, "SecureChannel was rejected");
   105	        scs->rejectedChannelCount++;
   106	        break;
   107	    case UA_SHUTDOWNREASON_ABORT:
   108	        UA_LOG_INFO_CHANNEL(sc->logging, channel, "SecureChannel was aborted");
   109	        scs->channelAbortCount++;
   110	        break;
   111	    default:
   112	        UA_assert(false);
   113	        break;
   114	    }
   115	
   116	    /* Notify the application */
   117	    notifySecureChannel(server, channel,
   118	                        UA_APPLICATIONNOTIFICATIONTYPE_SECURECHANNEL_CLOSED);
   119	
   120	    /* Clean up the SecureChannel. This is the only place where
   121	     * UA_SecureChannel_clear must be called within the server code-base. */
   122	    UA_SecureChannel_clear(channel);
   123	    UA_free(channel);
   124	}
