   311	UA_StatusCode
   312	sendResponse(UA_Server *server, UA_SecureChannel *channel, UA_UInt32 requestId,
   313	             UA_Response *response, const UA_DataType *responseType) {
   314	    if(!channel)
   315	        return UA_STATUSCODE_BADINTERNALERROR;
   316	
   317	    /* If the overall service call failed, answer with a ServiceFault */
   318	    if(response->responseHeader.serviceResult != UA_STATUSCODE_GOOD)
   319	        return sendServiceFault(server, channel, requestId,
   320	                                response->responseHeader.requestHandle,
   321	                                response->responseHeader.serviceResult);
